$errors = []; $plan = []; $removals = [];

$byFile = [];
foreach ($edits as $edit) { $byFile[$edit[0]][] = $edit; }

foreach ($byFile as $path => $list) {
    if (!is_file($path)) { $errors[] = "$path is missing"; continue; }
    $raw = file_get_contents($path); $crlf = str_contains($raw, "\r\n"); $text = $norm($raw);
    foreach ($list as $edit) {
        if ($edit[1] === 'R') {
            [, , $find, $replace] = $edit;
            if (substr_count($text, $find) !== 1) { $errors[] = "$path: expected text not found exactly once: " . trim(substr($find, 0, 70)); continue 2; }
            $text = str_replace($find, $replace, $text);
        } elseif ($edit[1] === 'RB') {
            [, , $pattern, $replace, $expected] = $edit;
            $text = preg_replace_callback($pattern, fn () => $replace, $text, -1, $count);
            if ($count !== $expected) { $errors[] = "$path: expected $expected matches, found $count"; continue 2; }
        } elseif ($edit[1] === 'RA') {
            [, , $pattern, $replace, $expected] = $edit;
            $text = preg_replace($pattern, $replace, $text, -1, $count);
            if ($count !== $expected) { $errors[] = "$path: expected $expected matches of $pattern, found $count"; continue 2; }
        } else {
            [, , $from, $to, $replacement] = $edit;
            if (substr_count($text, $from) !== 1 || substr_count($text, $to) !== 1) { $errors[] = "$path: expected block not found exactly once: " . trim(substr($from, 0, 70)); continue 2; }
            $start = strpos($text, $from); $end = strpos($text, $to, $start);
            if ($end === false) { $errors[] = "$path: markers out of order"; continue 2; }
            $text = substr($text, 0, $start) . $replacement . substr($text, $end);
        }
    }
    $plan[] = [$path, $text, $crlf];
}

foreach ($wholesale as [$path, $sha, $content]) {
    if (!is_file($path)) { $errors[] = "$path is missing"; continue; }
    $raw = file_get_contents($path);
    if (sha1($norm($raw)) !== $sha) { $errors[] = "$path does not match the expected content (was it edited, or is this patch already applied?)"; continue; }
    $plan[] = [$path, $content, str_contains($raw, "\r\n")];
}

foreach ($deleted as [$path, $sha]) {
    if (!is_file($path)) { $errors[] = "$path is missing"; continue; }
    if (sha1($norm(file_get_contents($path))) !== $sha) { $errors[] = "$path does not match the expected content (was it edited?)"; continue; }
    $removals[] = $path;
}

foreach ($created as [$path, $content]) {
    if (is_file($path)) { $errors[] = "$path already exists"; continue; }
    $plan[] = [$path, $content, false];
}

if ($errors) {
