}

foreach ($plan as [$path, $text, $crlf]) {
    $existed = is_file($path);
    if ($crlf) { $text = str_replace("\n", "\r\n", $text); }
    @mkdir(dirname($path), 0777, true);
    file_put_contents($path, $text);
    echo ($existed ? "patched  " : "created  ") . "$path\n";
}
foreach ($removals as $path) { unlink($path); echo "deleted  $path\n"; }
